-- "Treasures of Minas": sacred art and everyday objects from Museu do Ouro
-- (Sabará) and Museu Regional Casa dos Ottoni (Serro), both Ibram museums.
-- See the row's source_note for sources and what the captions avoid claiming.
--
-- Run by hand in Neon's SQL editor. Re-runnable: the storyline is
-- ON CONFLICT DO NOTHING and items are tagged only once.

INSERT INTO storylines (id, title, type, tier, cover_item_id, intro_caption, source_note, items) VALUES ('treasures-of-minas', 'Treasures of Minas', 'shared_place', 'narrative', 'museudoouro:6019', 'In 18th-century Minas Gerais, the gold rush brought settlers faster than churches were built for them. The Portuguese Crown suspected friars of helping to smuggle gold, so it kept the religious orders out of Minas. Instead, brotherhoods of ordinary believers hired the priests and built the churches. Devotion also lived at home, in front of small household altars called oratórios. Two federal museums keep objects from that world close to where they were made. Museu do Ouro in Sabará occupies the Casa de Intendência e Fundição, where the Portuguese Crown smelted and taxed the region''s gold in the 18th century. Museu Regional Casa dos Ottoni in Serro is the house where the brothers Teófilo and Cristiano Ottoni were born. Here the two collections meet: small saints made for household altars, the silver and gilded wood of the church, and a few things from everyday life.', 'SOURCES: every chapter caption is drawn from the holding museum''s own catalogue record on its Tainacan site (museudoouro.acervos.museus.gov.br, museuregionalcasadosottoni.acervos.museus.gov.br): the description, stylistic, iconographic and historical-data fields, read 26 Oct 2026. The intro''s museum history comes from Ibram''s published material for each museum: Museu do Ouro occupies Sabará''s former Casa de Intendência e Fundição; Teófilo and Cristiano Ottoni were born in the Serro house. RELIGIOUS CONTEXT (intro): the Crown barred religious orders from Minas over gold smuggling, and lay brotherhoods hired clergy and built churches (Revista de História da UEG, ''Associações religiosas de leigos no período colonial'', https://www.revista.ueg.br/index.php/revistahistoria/article/view/9753); oratórios as pieces of household devotion, miniature altarpieces (Boletim do CEIB, https://eba.ufmg.br/boletimceib/index.php/boletimdoceib/article/download/40/29/52). SELECTION: sacred art first, then one signed domestic object and one piece of furniture, then the portrait of the Ottoni museum''s namesake. EXCLUDED: São José de Botas (museudoouro:5939), whose source record carries a photograph of a different object. NOT CLAIMED: the record does not explain the title ''São Francisco dos Espinhos'', so that caption describes the carving only; the bed''s monogram is recorded both as ''JMS'' and ''JMJ''; the photograph shows JMJ; the Christ Child''s Portuguese origin is bracketed (attributed) in the record, hence ''tentatively''; the reliquary''s record does not say what relic it held; ''lapinha'' is not glossed, for want of a dictionary source.', '[{"id": "museudoouro:6019", "position": 1, "chapter_caption": "An oratório is a household altar: a cabinet, a miniature altarpiece, where a family kept its saints and prayed. This one, from late-18th-century Minas, is in the rococo taste. Its painted doors show two virgin martyrs, each holding the palm of martyrdom: Saint Barbara, with the chalice that promised a good death, with the sacraments, to those who asked her help, and Saint Lucy, with her dish of eyes. Inside, small soapstone figures include Our Lady of the Conception and Saint Manuel, a Persian Christian martyred in the 4th century."}, {"id": "museudoouro:6427", "position": 2, "chapter_caption": "Nine centimeters tall and carved in soapstone, this Virgin was made for an oratory like the one before it. She stands on a globe and clouds with three angel heads, hands joined in prayer. Our Lady of the Conception was patroness of the Portuguese empire from 1646, and the first parish churches of Minas were dedicated to her."}, {"id": "casadosottoni:36551", "position": 3, "chapter_caption": "From the Casa dos Ottoni in Serro, a small rococo oratory of carved, painted and gilded cedar and Riga pine. Inside is a blue sky with a stylized white cloud, painted roses on the walls and ceiling, and a dark green cross; a gilded openwork shell crowns the top."}, {"id": "casadosottoni:36527", "position": 4, "chapter_caption": "A baroque Christ Child in carved and painted wood, with glass eyes; the museum tentatively gives his origin as Portugal. He is a plump infant with one hand raised to his mouth. A hole in his back suggests he was once fitted onto something else."}, {"id": "casadosottoni:36585", "position": 5, "chapter_caption": "Saint Francis lies with his body twisted, wearing only a white loincloth, with red wounds painted on his arms, hands, back, chest, legs and feet. The 19th-century carving from Minas is known as São Francisco dos Espinhos: Saint Francis of the Thorns."}, {"id": "museudoouro:6505", "position": 6, "chapter_caption": "A reliquary in the shape of a raised right arm, in gilded and painted wood. The oval niche in its sleeve was made to display a relic. Relics are usually a fragment of a saint''s body or of something the saint touched; the record does not say what this one held. As the museum''s record notes, from the 4th century a relic was required to consecrate a church."}, {"id": "museudoouro:6131", "position": 7, "chapter_caption": "A monstrance, made to display the consecrated host, in gilded silver: 59 centimeters tall and over three kilograms. Inside its round window, a gold crescent with three angel heads held the host. It bears no maker''s mark; the museum considers it probably Brazilian."}, {"id": "museudoouro:5879", "position": 8, "chapter_caption": "Not everything here was made for the church. This plain clay water jug carries its maker''s own words near the mouth: Atanásio Carneiro da Silva made it on 16 April 1814."}, {"id": "casadosottoni:36838", "position": 9, "chapter_caption": "An 18th-century double bed in jacaranda, its headboard lined with turned and twisted spindles under a triangular pediment carved with JMJ, for Jesus, Maria and José. Holes at the corners once held the posts of a canopy."}, {"id": "casadosottoni:36039", "position": 10, "chapter_caption": "The man the museum is named for: Teófilo Benedicto Ottoni, in a 19th-century lithograph printed in Rio de Janeiro. He and his brother Cristiano, both later senators, were born in the Serro house that is now the Museu Regional Casa dos Ottoni."}]'::jsonb) ON CONFLICT (id) DO NOTHING;

UPDATE items SET storyline_ids = array_append(COALESCE(storyline_ids, '{}'), 'treasures-of-minas')
WHERE native_id IN ('museudoouro:6019', 'museudoouro:6427', 'casadosottoni:36551', 'casadosottoni:36527', 'casadosottoni:36585', 'museudoouro:6505', 'museudoouro:6131', 'museudoouro:5879', 'casadosottoni:36838', 'casadosottoni:36039')
  AND NOT ('treasures-of-minas' = ANY(COALESCE(storyline_ids, '{}')));
